    func load(_ json: String) throws -> Game {
        let s = try JSONDecoder().decode(GameState.self, from: Data(json.utf8))
        return Game(state: s, seed: 5)
    }

    func days(_ g: inout Game, _ n: Int) {
        for _ in 0..<n {
            g.startDay()
            while g.nextHezarfen() != nil {}
            _ = g.launch(skip: g.state.weather?.flag == .red)
            _ = g.finishDay(flight: nil)
        }
    }

    func testV130SavesLoadAndPlayOn() throws {
        for (name, json) in Self.saves {
            var g = try load(json)
            let day0 = g.state.day, owned = RegionID.allCases.filter { g.state.owns($0) }
            days(&g, 12)
            XCTAssertEqual(g.state.day, day0 + 12, name)
            XCTAssertFalse(g.state.over, name)
            XCTAssertEqual(RegionID.allCases.filter { g.state.owns($0) }, owned, "\(name): the same regions")
            for r in owned where r != g.state.region { g.switchRegion(r); days(&g, 2) }
            // a round trip through today's encoder
            let back = try JSONDecoder().decode(GameState.self, from: JSONEncoder().encode(g.state))
            XCTAssertEqual(back, g.state, name)
        }
    }

    func testCargoOnItsWayArrivesAfterLoading() throws {
        var g = try load(Self.saves[1].1)
        XCTAssertEqual(g.state.region, .lux)
        let ship = try XCTUnwrap(g.state.local.transferShip)
        let ids = ship.balloons.map(\.id)
        days(&g, max(0, ship.day - g.state.day) + 1)
        XCTAssertNil(g.state.local.transferShip)
        XCTAssertTrue(ids.allSatisfy { id in g.state.local.balloons.contains { $0.id == id } })
    }

    func testOldHoldingGoesOnToTheMara() throws {
        var g = try load(Self.saves[2].1)
        XCTAssertTrue(g.state.holding.has(.ist))
        XCTAssertTrue(g.state.holding.has(.nyc))
        XCTAssertFalse(g.canOpenOffice(.dxb), "Dubai waits for the Mara")
        g.state.barons[.bri] = g.state.day
        g.state.holding.cash += RegionID.mara.entryFee
        XCTAssertTrue(g.enterRegion(.mara))
        XCTAssertTrue(g.canOpenOffice(.dxb))
        let d = g.transferDefaults
        g.applyTransfer(balloons: d.balloons, pilots: d.pilots)
        days(&g, 11)
        XCTAssertEqual(g.state.region, .mara)
        XCTAssertFalse(g.state.over)
    }
